mapper.select:
/*selectSellerMpClCatalogList*/ SELECT A.BUYER_ITEM_NO AS BUYER_ITEM_NO, A.DESCRIPTION AS DESCRIPTION, A.SPECIFICATION AS SPECIFICATION, A.UNIT_MEASURE AS UNIT_MEASURE, A.LIST_PRICE AS LIST_PRICE, A.MAKER_NAME AS MAKER_NAME, (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M001' AND A.ORIGIN_CODE = CODE) AS ORIGIN_NAME, A.ADD_DATE AS ADD_DATE, A.CHANGE_DATE AS CHANGE_DATE, A.BUYER AS BYIT_COMORG_CODE, A.BELOW_COMORG_CODE AS BUYER, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.BELOW_COMORG_CODE) AS BUYER_NAME, A.CONTRACT_NO AS CONTRACT_NO, A.CONTRACT_SEQ AS CONTRACT_SEQ, A.SELLER_ITEM_NO AS SELLER_ITEM_NO, A.AGENT, DECODE (A.S_STOCK_FLAG, 'Y', '재고') AS S_STOCK_FLAG, B.IMGFILE_NAME, B.IMGFILE_DIR, B.DETAIL_IMGFILE_NAME, B.DETAIL_IMGFILE_DIR, KEP.F_GET_KEPREQIMG_STT(A.BELOW_COMORG_CODE, A.BUYER_ITEM_NO, A.AGENT,0) AS IMG_STATUS_CD, KEP.F_GET_KEPREQIMG_STT(A.BELOW_COMORG_CODE, A.BUYER_ITEM_NO, A.AGENT,1) AS IMG_STATUS_NM FROM ICOMCQDT A, ICOMBYIT B WHERE 1=1
AND A.BUYER IN
#{item}
AND A.AGENT = #{st_com_code} AND A.DESCRIPTION LIKE '%'||#{st_description}||'%' AND A.SPECIFICATION LIKE '%'||#{st_specification}||'%' AND A.BUYER_ITEM_NO LIKE '%'||#{st_buyer_item_no}||'%' AND A.STATUS <> 'D' AND B.STATUS <> 'D' AND A.BUYER = B.BUYER AND A.BUYER_ITEM_NO = B.BUYER_ITEM_NO AND B.PRODUCT_CLOSE_FLAG IN ('N', 'T') ORDER BY A.BUYER_ITEM_NO

