mapper.select:
SELECT * FROM ( SELECT ROWNUM AS RN, T.* FROM (
/*selectSellerMpClCatalogListV2Paging - 리뉴얼 무한스크롤*/ SELECT A.BUYER_ITEM_NO AS ITEM_CODE, A.DESCRIPTION AS ITEM_NAME, A.SPECIFICATION AS SPECIFICATION, A.UNIT_MEASURE AS UNIT, A.LIST_PRICE AS CONTRACT_PRICE, A.MAKER_NAME AS MANUFACTURER, (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M001' AND A.ORIGIN_CODE = CODE) AS ORIGIN, A.BELOW_COMORG_CODE AS BUYER_CODE, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.BELOW_COMORG_CODE) AS BUYER_NAME, CASE WHEN B.IMGFILE_DIR IS NOT NULL AND B.IMGFILE_NAME IS NOT NULL AND TRIM(B.IMGFILE_DIR) != '' AND TRIM(B.IMGFILE_NAME) != '' THEN B.IMGFILE_DIR || B.IMGFILE_NAME ELSE '/resources/imgs/noimage.gif' END AS PRODUCT_IMAGE, CASE WHEN B.DETAIL_IMGFILE_DIR IS NOT NULL AND B.DETAIL_IMGFILE_NAME IS NOT NULL AND TRIM(B.DETAIL_IMGFILE_DIR) != '' AND TRIM(B.DETAIL_IMGFILE_NAME) != '' THEN B.DETAIL_IMGFILE_DIR || B.DETAIL_IMGFILE_NAME ELSE '/resources/imgs/noimage.gif' END AS DETAIL_IMAGE, KEP.F_GET_KEPREQIMG_STT(A.BELOW_COMORG_CODE, A.BUYER_ITEM_NO, A.AGENT, 0) AS IMAGE_STATUS_CODE, KEP.F_GET_KEPREQIMG_STT(A.BELOW_COMORG_CODE, A.BUYER_ITEM_NO, A.AGENT, 1) AS IMAGE_STATUS, TO_CHAR(TO_DATE(A.ADD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS REG_DATE, TO_CHAR(TO_DATE(A.CHANGE_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS MOD_DATE, CASE WHEN K.IMGFILE_NAME IS NOT NULL THEN '첨부(1)' ELSE '첨부' END AS IMAGE_REGISTER, CASE WHEN K.DETAIL_IMGFILE_NAME IS NOT NULL THEN '첨부(1)' ELSE '첨부' END AS DETAIL_REGISTER, A.CONTRACT_NO AS CONTRACT_NO, A.CONTRACT_SEQ AS CONTRACT_SEQ, A.SELLER_ITEM_NO AS SELLER_ITEM_NO, A.AGENT, DECODE (A.S_STOCK_FLAG, 'Y', '재고') AS S_STOCK_FLAG, B.IMGFILE_NAME, B.IMGFILE_DIR, B.DETAIL_IMGFILE_NAME, B.DETAIL_IMGFILE_DIR, A.BUYER AS BYIT_COMORG_CODE, B.CATEGORY_TEXT AS CATEGORY_TEXT, B.IMAGE_KEY AS DOC_NO, B.MSDS_YN AS MSDS_YN, B.MSDS_ATTACH_YN AS MSDS_ATTACH_YN, B.MSDS_NO AS MSDS_NO, A.DELIVERY_LT AS DELIVERY_LT FROM ICOMCQDT A INNER JOIN ICOMBYIT B ON A.BUYER = B.BUYER AND A.BUYER_ITEM_NO = B.BUYER_ITEM_NO LEFT JOIN KEPREQIMG K ON A.BELOW_COMORG_CODE = K.BUYER AND A.BUYER_ITEM_NO = K.BUYER_ITEM_NO AND A.AGENT = K.AGENT AND K.STATUS != 'D' AND K.IMG_REQ_NO = ( SELECT MAX(K2.IMG_REQ_NO) FROM KEPREQIMG K2 WHERE K2.BUYER = K.BUYER AND K2.BUYER_ITEM_NO = K.BUYER_ITEM_NO AND K2.AGENT = K.AGENT AND K2.STATUS != 'D' ) WHERE 1=1
AND A.BUYER IN
#{item}
AND KEP.F_GET_KEPREQIMG_STT(A.BELOW_COMORG_CODE, A.BUYER_ITEM_NO, A.AGENT, 0) = #{imageStatus}
AND A.BUYER_ITEM_NO LIKE '%'||#{itemCode}||'%'
AND A.MAKER_NAME LIKE '%'||#{manufacturer}||'%'
AND A.DESCRIPTION LIKE '%'||#{itemName}||'%'
AND A.SPECIFICATION LIKE '%'||#{specification}||'%'
AND A.AGENT = #{st_com_code} AND A.STATUS <> 'D' AND B.STATUS <> 'D' AND B.PRODUCT_CLOSE_FLAG IN ('N', 'T') ORDER BY A.BUYER_ITEM_NO ) T WHERE ROWNUM <= #{endRow} ) WHERE RN > #{startRow}

/*selectSellerMpClCatalogListV2Count - 리뉴얼 무한스크롤 총건수*/ SELECT COUNT(*) FROM ICOMCQDT A INNER JOIN ICOMBYIT B ON A.BUYER = B.BUYER AND A.BUYER_ITEM_NO = B.BUYER_ITEM_NO WHERE 1=1
AND A.BUYER IN
#{item}
AND KEP.F_GET_KEPREQIMG_STT(A.BELOW_COMORG_CODE, A.BUYER_ITEM_NO, A.AGENT, 0) = #{imageStatus}
AND A.BUYER_ITEM_NO LIKE '%'||#{itemCode}||'%'
AND A.MAKER_NAME LIKE '%'||#{manufacturer}||'%'
AND A.DESCRIPTION LIKE '%'||#{itemName}||'%'
AND A.SPECIFICATION LIKE '%'||#{specification}||'%'
AND A.AGENT = #{st_com_code} AND A.STATUS <> 'D' AND B.STATUS <> 'D' AND B.PRODUCT_CLOSE_FLAG IN ('N', 'T')
